package cn.zhuatech.bpm.deep;import cn.zhuatech.bpm.common.ApiResponse;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/workflow-ops") public class DeepWorkflowController{private final DeepWorkflowService s;public DeepWorkflowController(DeepWorkflowService x){s=x;}@GetMapping("/workspace")ApiResponse<?> workspace(){return ApiResponse.ok(s.workspace());}@PostMapping("/instances")ApiResponse<?> start(@RequestBody DeepWorkflowService.StartInput x){return ApiResponse.ok(s.start(x));}@PostMapping("/tasks/{id}/claim")ApiResponse<?> claim(@PathVariable Long id,@RequestBody DeepWorkflowService.ClaimInput x){return ApiResponse.ok(s.claim(id,x));}@PostMapping("/tasks/{id}/delegate")ApiResponse<?> delegate(@PathVariable Long id,@RequestBody DeepWorkflowService.ClaimInput x){return ApiResponse.ok(s.delegate(id,x));}@PostMapping("/tasks/{id}/decision")ApiResponse<?> decide(@PathVariable Long id,@RequestBody DeepWorkflowService.DecisionInput x){return ApiResponse.ok(s.decide(id,x));}}
